"""Structured story choices verified against scans; no free-text semantic guessing.
Variants are appropriate complete contexts with questions; child supplies operation
and result, and supplies quantities where the original leaves numbers open.
"""
def step(id,question,op,left,right):return dict(id=id,question=question,operator=op,left=left,right=right)
def inp(id,label,max=100):return dict(id=id,label=label,min=1,max=max)
def var(id,label,description,steps,inputs=None):
 d=dict(id=id,label=label,description=description,steps=steps)
 if inputs:d['inputs']=inputs
 return d
def spec(unit,max,variants,inputs=None):
 d=dict(unit=unit,max=max,variants=variants,operationChoices=['+','−'] if max==10 else ['+','−','×',':'])
 if inputs:d['inputs']=inputs
 return dict(kind='story',story=d)
def ref(name):return dict(input=name)
PREV=dict(result='first')
